import{_ as e,o as l,c as a,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const c=JSON.parse('{"title":"巴菲特之道","description":"","frontmatter":{},"headers":[],"relativePath":"09_books/巴菲特之道/README.md","filePath":"09_books/巴菲特之道/README.md"}'),n={name:"09_books/巴菲特之道/README.md"};function i(o,t,s,d,h,g){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="巴菲特之道" tabindex="-1">巴菲特之道 <a class="header-anchor" href="#巴菲特之道" aria-label="Permalink to &quot;巴菲特之道&quot;">​</a></h1><blockquote><p><strong>作者：</strong> Robert G. Hagstrom | <strong>翻译：</strong> 杨天南 | <strong>版本：</strong> 第3版 | <strong>出版：</strong> 2015</p></blockquote><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>《巴菲特之道》是第一本将巴菲特思想引进中国的书，自1994年出版以来，已畅销120万册。本书系统性地总结了巴菲特投资方法的四大类12条准则。</p><blockquote><p><strong>&quot;本书揭示出，巴菲特的成就就是非凡的，巴菲特的投资方法也是非凡的，但他的方法却是可以为普通投资者所学习和应用的。&quot;</strong> —— 《华尔街日报》</p></blockquote><hr><h2 id="核心框架-四大类12条准则" tabindex="-1">核心框架：四大类12条准则 <a class="header-anchor" href="#核心框架-四大类12条准则" aria-label="Permalink to &quot;核心框架：四大类12条准则&quot;">​</a></h2><h3 id="一、企业准则" tabindex="-1">一、企业准则 <a class="header-anchor" href="#一、企业准则" aria-label="Permalink to &quot;一、企业准则&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">准则</th><th style="text-align:left;">描述</th><th style="text-align:left;">关联主题</th></tr></thead><tbody><tr><td style="text-align:left;">简单易懂</td><td style="text-align:left;">你能理解公司的业务模式</td><td style="text-align:left;"><a href="/02_concepts/circle-of-competence">能力圈</a></td></tr><tr><td style="text-align:left;">稳定业务</td><td style="text-align:left;">拥有持续稳定的运营历史</td><td style="text-align:left;"><a href="/02_concepts/long-term">长期主义</a></td></tr><tr><td style="text-align:left;">长期前景</td><td style="text-align:left;">具有长期竞争优势（护城河）</td><td style="text-align:left;"><a href="/02_concepts/moat">护城河</a></td></tr></tbody></table><h3 id="二、管理准则" tabindex="-1">二、管理准则 <a class="header-anchor" href="#二、管理准则" aria-label="Permalink to &quot;二、管理准则&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">准则</th><th style="text-align:left;">描述</th><th style="text-align:left;">关联主题</th></tr></thead><tbody><tr><td style="text-align:left;">理性</td><td style="text-align:left;">管理层能理性配置公司资源</td><td style="text-align:left;"><a href="/02_concepts/capital-allocation">资本配置</a></td></tr><tr><td style="text-align:left;">坦诚</td><td style="text-align:left;">管理层对股东开诚布公</td><td style="text-align:left;"><a href="/02_concepts/reputation">声誉经济</a></td></tr><tr><td style="text-align:left;">独立思考</td><td style="text-align:left;">管理层能抵制惯性驱使</td><td style="text-align:left;"><a href="/02_concepts/contrarian">逆向思维</a></td></tr></tbody></table><h3 id="三、财务准则" tabindex="-1">三、财务准则 <a class="header-anchor" href="#三、财务准则" aria-label="Permalink to &quot;三、财务准则&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">准则</th><th style="text-align:left;">描述</th><th style="text-align:left;">关联主题</th></tr></thead><tbody><tr><td style="text-align:left;">净资产收益率</td><td style="text-align:left;">衡量股东回报的核心指标</td><td style="text-align:left;"><a href="/02_concepts/intrinsic-value">内在价值</a></td></tr><tr><td style="text-align:left;">股东回报率</td><td style="text-align:left;">关注留存收益的复利效应</td><td style="text-align:left;"><a href="/02_concepts/compounding">复利</a></td></tr><tr><td style="text-align:left;">利润率</td><td style="text-align:left;">企业定价权的体现</td><td style="text-align:left;"><a href="/02_concepts/safety-margin">安全边际</a></td></tr></tbody></table><h3 id="四、市场准则" tabindex="-1">四、市场准则 <a class="header-anchor" href="#四、市场准则" aria-label="Permalink to &quot;四、市场准则&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">准则</th><th style="text-align:left;">描述</th><th style="text-align:left;">关联主题</th></tr></thead><tbody><tr><td style="text-align:left;">安全边际</td><td style="text-align:left;">买入价格与价值之间的缓冲</td><td style="text-align:left;"><a href="/02_concepts/safety-margin">安全边际</a></td></tr><tr><td style="text-align:left;">股票市值</td><td style="text-align:left;">市场规模与公司价值的匹配</td><td style="text-align:left;"><a href="/search?q=市场先生">市场先生</a></td></tr></tbody></table><hr><h2 id="投资案例" tabindex="-1">投资案例 <a class="header-anchor" href="#投资案例" aria-label="Permalink to &quot;投资案例&quot;">​</a></h2><p>本书深入分析了12个经典投资案例：</p><ol><li><strong>华盛顿邮报</strong> - 1973年投资</li><li><strong>盖可保险</strong> - 1951年首次投资，1996年全资收购</li><li><strong>可口可乐</strong> - 1988年重仓投资</li><li><strong>富国银行</strong> - 1990年投资</li><li><strong>美国运通</strong> - 1964年投资</li><li><strong>吉列</strong> - 1989年投资</li><li><strong>箭牌</strong> - 2006年收购</li><li><strong>伯灵顿北方圣达菲铁路</strong> - 2009年投资</li><li><strong>IBM</strong> - 2011年投资</li><li><strong>苹果</strong> - 2016年投资</li><li><strong>美国银行</strong> - 2011年投资</li><li><strong>日本五大商事</strong> - 2020年投资</li></ol><hr><h2 id="与知识库联动" tabindex="-1">与知识库联动 <a class="header-anchor" href="#与知识库联动" aria-label="Permalink to &quot;与知识库联动&quot;">​</a></h2><p>本书内容与巴菲特致股东信70年内容高度契合：</p><ul><li>四大类准则 → 对应<a href="/search?q=25个投资主题">25个投资主题</a></li><li>12个投资案例 → 对应<a href="/search?q=34家公司档案">34家公司档案</a></li><li>投资心理学 → 对应<a href="/search?q=行为金融学">行为金融学</a></li><li>耐心价值 → 对应<a href="/02_concepts/compounding">复利</a>和<a href="/02_concepts/long-term">长期主义</a></li></ul><hr><h2 id="扩展阅读" tabindex="-1">扩展阅读 <a class="header-anchor" href="#扩展阅读" aria-label="Permalink to &quot;扩展阅读&quot;">​</a></h2><ul><li><a href="/search?q=穷查理宝典">穷查理宝典</a> - 芒格思想精华</li><li><a href="/04_people/本·格雷厄姆">格雷厄姆</a> - 价值投资之父</li><li><a href="/04_people/菲利普·费雪">费雪</a> - 成长股投资之父</li></ul>',26)])])}const x=e(n,[["render",i]]);export{c as __pageData,x as default};
